    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 3) NOT NULL,
    "ACTIVO" BOOLEAN NOT NULL,
    "CODIGO" CHARACTER VARYING(30) NOT NULL,
    "DESCRIPCION" CHARACTER VARYING(255),
    "MAX_USUARIOS" INTEGER,
    "NOMBRE" CHARACTER VARYING(100) NOT NULL,
    "PRECIO_ANUAL" NUMERIC(12, 2) NOT NULL,
    "PRECIO_MENSUAL" NUMERIC(12, 2) NOT NULL
);               
ALTER TABLE "PUBLIC"."PLANES_SUSCRIPCION" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_2E" PRIMARY KEY("ID");          
