CREATE MEMORY TABLE "PUBLIC"."PRODUCTOS"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 90) NOT NULL,
    "ACTIVO" BOOLEAN NOT NULL,
    "CATEGORIA" CHARACTER VARYING(100),
    "CODIGO" CHARACTER VARYING(50) NOT NULL,
    "CODIGO_BARRAS" CHARACTER VARYING(100),
    "CONCENTRACION" CHARACTER VARYING(100),
    "CONTROL_STOCK_ESPECIAL" BOOLEAN NOT NULL,
    "COSTO_UNITARIO" NUMERIC(12, 2),
    "DESCRIPCION" CHARACTER VARYING(500),
    "FECHA_VENCIMIENTO" DATE,
    "FORMA_FARMACEUTICA" CHARACTER VARYING(100),
    "IMAGEN_URL" CHARACTER VARYING(255),
    "LABORATORIO" CHARACTER VARYING(100) NOT NULL,
    "LISTA_CONTROL" CHARACTER VARYING(30),
    "LOTE" CHARACTER VARYING(50),
    "MARCA" CHARACTER VARYING(100),
    "NOMBRE" CHARACTER VARYING(200) NOT NULL,
    "PRECIO_VENTA" NUMERIC(12, 2) NOT NULL,
    "PRESENTACION" CHARACTER VARYING(50) NOT NULL,
    "PRINCIPIO_ACTIVO" CHARACTER VARYING(200),
    "REGISTRO_SANITARIO" CHARACTER VARYING(50),
    "REQUIERE_RECETA" BOOLEAN NOT NULL,
    "STOCK_ACTUAL" INTEGER NOT NULL,
    "STOCK_MAXIMO" INTEGER,
    "STOCK_MINIMO" INTEGER NOT NULL,
    "TENANT_ID" BIGINT NOT NULL,
    "TIPO_CONTROL_DIGEMID" CHARACTER VARYING(30),
    "TIPO_PRODUCTO_CONTROLADO" CHARACTER VARYING(30),
    "TIPO_RECETA" CHARACTER VARYING(30),
    "UNIDAD_MEDIDA" CHARACTER VARYING(30)
);              
ALTER TABLE "PUBLIC"."PRODUCTOS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_67666A" PRIMARY KEY("ID");               
